-- Embedded PNG data only, never executable code or a remote script.
local EMBEDDED_LOGO_BASE64 = ""
local function decodeLogo(encoded, cancelled)
 local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
 local lookup={}
 for index=1,#alphabet do lookup[alphabet:byte(index)]=index-1 end
 local chunks,bytes={},{}
 for index=1,#encoded,4 do
  if index%65536==1 then
   if cancelled() then return nil end
   task.wait()
  end
  local a,b,c,d=encoded:byte(index,index+3)
  local value=lookup[a]*262144+lookup[b]*4096+(lookup[c] or 0)*64+(lookup[d] or 0)
  local part=string.char(math.floor(value/65536)%256)
  if c~=61 then part=part..string.char(math.floor(value/256)%256) end
  if d~=61 then part=part..string.char(value%256) end
  bytes[#bytes+1]=part
  if #bytes>=4096 then chunks[#chunks+1]=table.concat(bytes) bytes={} end
 end
 chunks[#chunks+1]=table.concat(bytes)
 return table.concat(chunks)
end
