local function on(signal, callback)
 local connection = signal:Connect(callback)
 table.insert(connections, connection)
 return connection
end
local function create(class, props, owner)
 local object = Instance.new(class)
 for key,value in pairs(props) do object[key]=value end
 object.Parent=owner
 return object
end
local function rounded(object, radius)
 local existing=object:FindFirstChildOfClass("UICorner")
 local corner=existing or create("UICorner",{},object)
 corner.CornerRadius=UDim.new(0,radius or 12)
 return corner
end
local function frame(owner, x,y,w,h,color)
 local object=create("Frame",{Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),BackgroundColor3=color or C.panel,BorderSizePixel=0},owner)
 rounded(object)
 return object
end
local function text(owner, value,x,y,w,h,size,color)
 return create("TextLabel",{Text=value,Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),BackgroundTransparency=1,TextColor3=color or C.text,Font=Enum.Font.GothamMedium,TextSize=size or 14,TextXAlignment=Enum.TextXAlignment.Left,TextWrapped=true},owner)
end
local function animate(object, props)
 if tweens[object] then tweens[object]:Cancel() end
 local tween=TweenService:Create(object,TweenInfo.new(reduced and 0 or .22,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),props)
 tweens[object]=tween
 tweenGoals[object]=props
 tween:Play()
end
local function finishMotion()
 for object,tween in pairs(tweens) do
  tween:Cancel()
  if object.Parent and tweenGoals[object] then
   for property,value in pairs(tweenGoals[object]) do object[property]=value end
  end
 end
end
local function button(owner, value,x,y,w,h,callback)
 local object=create("TextButton",{Text=value,Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),BackgroundColor3=C.card,TextColor3=C.text,Font=Enum.Font.GothamMedium,TextSize=13,AutoButtonColor=false},owner)
 rounded(object,9)
 local pressScale=create("UIScale",{Scale=1},object)
 create("UIStroke",{Color=C.line,Transparency=.5,Thickness=1},object)
 on(object.MouseEnter,function() animate(object,{BackgroundColor3=C.line}) end)
 on(object.MouseLeave,function() animate(object,{BackgroundColor3=C.card}) end)
 on(object.InputBegan,function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then animate(pressScale,{Scale=.975}) end
 end)
 on(object.InputEnded,function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then animate(pressScale,{Scale=1}) end
 end)
 on(object.MouseLeave,function() animate(pressScale,{Scale=1}) end)
 on(object.Activated,callback)
 return object
end
