-- Local PNG first where supported; Roblox image remains the Studio fallback.
task.spawn(function()
 local function applyImage(uri)
  if dead then return false end
  emblem.Image=uri
  monogram.Image=uri
  emblem.ImageColor3=Color3.new(1,1,1)
  monogram.ImageColor3=Color3.new(1,1,1)
  emblem.ImageTransparency=0
  monogram.ImageTransparency=0
  task.spawn(function() pcall(function() ContentProvider:PreloadAsync({monogram,emblem}) end) end)
  local deadline=os.clock()+8
  repeat
   if dead then return false end
   if emblem.IsLoaded and monogram.IsLoaded then updateLogoState() return true end
   task.wait(.1)
  until os.clock()>=deadline
  return false
 end
 local candidates={}
 if type(getcustomasset)=="function" then table.insert(candidates,{name="getcustomasset",fn=getcustomasset}) end
 if type(getsynasset)=="function" and getsynasset~=getcustomasset then table.insert(candidates,{name="getsynasset",fn=getsynasset}) end
 if type(writefile)=="function" and #candidates>0 then
  logoNotice.Text="Đang mở\nlogo tích hợp…"
  local ok,uri=pcall(function()
   local png=decodeLogo(EMBEDDED_LOGO_BASE64,function() return dead end)
   if dead or not png then return nil end
   assert(png:sub(1,8)=="\137PNG\r\n\26\n","Invalid embedded PNG")
   local path="kyvorix_logo_embedded_v3.png"
   writefile(path,png)
   return path
  end)
  if dead then return end
  if ok and type(uri)=="string" and #uri>0 then
   for _,candidate in ipairs(candidates) do
    if dead then return end
    local registered,localUri=pcall(candidate.fn,uri)
    if registered and type(localUri)=="string" and #localUri>0 and applyImage(localUri) then
     setLogoRoute("PNG tích hợp / "..candidate.name..": tải thành công") return
    end
    warn("KYVORIX logo route failed:",candidate.name,tostring(localUri))
   end
  else
   warn("KYVORIX local logo:",tostring(uri))
  end
 end
 if dead then return end
 logoNotice.Text="Đang tải\nảnh Roblox…"
 if LOGO_ASSET~="" and applyImage(LOGO_ASSET) then setLogoRoute("Roblox Image: tải thành công") return end
 if dead then return end
 updateLogoState()
 if not emblem.IsLoaded then
  setLogoRoute("Không tải được ở môi trường hiện tại")
  logoNotice.Text="Ảnh bị chặn\nhoặc chưa khả dụng"
  notify("Logo: môi trường không tải được ảnh. Xem Output để biết nguồn đã thử.")
  warn("KYVORIX: local image unavailable; Roblox image failed:",LOGO_ASSET,"getcustomasset:",type(getcustomasset),"writefile:",type(writefile))
 end
end)
