local function selectPage(name)
 active=name
 for key,p in pairs(pages) do p.root.Visible=key==name end
 for key,b in pairs(nav) do
  b.TextColor3=key==name and C.text or C.muted
  b.BackgroundTransparency=key==name and 0 or .65
  local marker=b:FindFirstChild("SelectionMarker")
  if marker then marker.Visible=key==name end
  local indicator=b:FindFirstChild("TabArrow")
  if indicator then indicator.Visible=key==name end
 end
 local p=pages[name].root
 pages[name].list.CanvasPosition=Vector2.zero
 p.Position=UDim2.fromOffset(8,0)
 animate(p,{Position=UDim2.fromOffset(0,0)})
end
for index,name in ipairs(names) do
 nav[name]=button(sidebar,string.format("%02d   %s",index,name),10,44+(index-1)*46,168,38,function() selectPage(name) end)
 nav[name].TextXAlignment=Enum.TextXAlignment.Left
 create("UIPadding",{PaddingLeft=UDim.new(0,12)},nav[name])
 local marker=frame(nav[name],-6,12,2,18,C.cyan)
 marker.Name="SelectionMarker"
 marker.Visible=false
 local arrow=text(nav[name],"›",143,8,14,26,19,C.cyan)
 arrow.Name="TabArrow"
 arrow.Visible=false
end
text(sidebar,"KYVORIX / DESIGN BUILD\nGameplay chưa tích hợp",16,468,160,44,10,C.muted)
-- Integrated UI features. No gameplay remotes or automation are invoked.
local HttpService=game:GetService("HttpService")
local paletteNames={"KYVORIX","Aurora","Hoàng hôn"}
local palettes={
 {C.cyan,C.purple},
 {Color3.fromRGB(120,220,196),Color3.fromRGB(130,176,234)},
 {Color3.fromRGB(229,163,180),Color3.fromRGB(222,197,138)},
}
local paletteIndex=1
local themeBindings={}
local themeButton
local function captureTheme()
 for _,object in ipairs(gui:GetDescendants()) do
  if object:IsA("UIGradient") then
   table.insert(themeBindings,{object=object,property="Color",original=object.Color,sequence=true})
  else
   local property
   if object:IsA("UIStroke") then property="Color"
   elseif object:IsA("TextLabel") or object:IsA("TextButton") then property="TextColor3"
   elseif object:IsA("Frame") then property="BackgroundColor3" end
   if property and (object[property]==C.cyan or object[property]==C.purple) then
    table.insert(themeBindings,{object=object,property=property,original=object[property]})
   end
  end
 end
end
local function applyPalette(index)
 paletteIndex=index
 local pair=palettes[index]
 local function recolor(color)
  if color==C.cyan then return pair[1] end
  if color==C.purple then return pair[2] end
  return color
 end
 for _,binding in ipairs(themeBindings) do
  if binding.sequence then
   local points={}
   for _,point in ipairs(binding.original.Keypoints) do
    points[#points+1]=ColorSequenceKeypoint.new(point.Time,recolor(point.Value))
   end
   binding.object[binding.property]=ColorSequence.new(points)
  else binding.object[binding.property]=recolor(binding.original) end
 end
 themeButton.Text=paletteNames[index]
end
local themeCard=card(names[7],"Bảng màu KYVORIX","Ba bảng màu dùng chung cho điểm nhấn và quỹ đạo, giữ nền tối dễ đọc.")
themeButton=button(themeCard,paletteNames[1],548,24,146,34,function()
 applyPalette(paletteIndex%#palettes+1)
end)
local profilePath="kyvorix_profile_"..tostring(player.UserId)..".json"
local function applyProfile(profile)
 if type(profile)~="table" or profile.version~=1 then error("Định dạng hồ sơ không hợp lệ") end
 if type(profile.reduced)~="boolean" or type(profile.aura)~="boolean" then error("Thiết lập hiệu ứng không hợp lệ") end
 if type(profile.palette)~="number" or profile.palette%1~=0 or not palettes[profile.palette] then error("Bảng màu không hợp lệ") end
 reduced=profile.reduced
 auraEnabled=profile.aura
 applyEffects()
 motionButton.Text=reduced and "Đang bật" or "Đang tắt"
 auraButton.Text=auraEnabled and "Đang bật" or "Đang tắt"
 for _,stroke in ipairs(auraStrokes) do stroke.Enabled=auraEnabled end
 applyPalette(profile.palette)
end
local profileCard=card(names[7],"Hồ sơ cá nhân","Lưu màu và hiệu ứng trên máy. Không lưu key, mật khẩu hoặc dữ liệu đăng nhập.",110)
profileCard.CardDescription.Size=UDim2.fromOffset(655,24)
button(profileCard,"Lưu hồ sơ",18,72,150,28,function()
 if type(writefile)~="function" then notify("Môi trường không hỗ trợ lưu file.") return end
 local ok,err=pcall(function()
  writefile(profilePath,HttpService:JSONEncode({version=1,reduced=reduced,aura=auraEnabled,palette=paletteIndex}))
 end)
 notify(ok and "Đã lưu hồ sơ giao diện trên máy." or "Không lưu được hồ sơ; xem Output.")
 if not ok then warn("KYVORIX profile save:",err) end
end)
button(profileCard,"Nạp hồ sơ",180,72,150,28,function()
 if type(readfile)~="function" then notify("Môi trường không hỗ trợ đọc file.") return end
 local ok,err=pcall(function()
  local raw=readfile(profilePath)
  assert(type(raw)=="string" and #raw<=4096,"Hồ sơ quá lớn hoặc không hợp lệ")
  applyProfile(HttpService:JSONDecode(raw))
 end)
 notify(ok and "Đã nạp hồ sơ giao diện." or "Không nạp được hồ sơ. File có thể chưa tồn tại hoặc bị lỗi.")
 if not ok then warn("KYVORIX profile load:",err) end
end)
button(profileCard,"Mặc định",342,72,150,28,function()
 applyProfile({version=1,reduced=false,aura=true,palette=1})
 notify("Đã khôi phục màu và hiệu ứng mặc định.")
end)
local overview=card(names[1],"Nhân vật / dữ liệu trực tiếp","",92)
overview.LayoutOrder=0
overview.CardDescription.Visible=false
local liveText=text(overview,"Đang đọc dữ liệu…",18,43,675,40,12,C.muted)
liveText.TextYAlignment=Enum.TextYAlignment.Top
local function readScalar(container,name)
 local value=container and container:FindFirstChild(name)
 if value and value:IsA("ValueBase") then
  local ok,result=pcall(function() return value.Value end)
  if ok and (type(result)=="number" or type(result)=="string") then return tostring(result) end
 end
 return "Chưa có dữ liệu"
end
local function updateOverview()
 local data=player:FindFirstChild("Data")
 local humanoid=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
 local health=humanoid and string.format("%.0f / %.0f",humanoid.Health,humanoid.MaxHealth) or "Đang chờ nhân vật"
 liveText.Text="Level: "..readScalar(data,"Level").."     Beli: "..readScalar(data,"Beli").."     Fragments: "..readScalar(data,"Fragments").."\nMáu: "..health
end
local overviewElapsed=0
on(RunService.Heartbeat,function(delta)
 if not window.Visible or active~=names[1] then return end
 overviewElapsed+=delta
 if overviewElapsed<1 then return end
 overviewElapsed=0
 updateOverview()
end)
captureTheme()
updateOverview()

local function fit()
 local size=gui.AbsoluteSize
 scale.Scale=math.max(.001,math.min(1,(size.X-20)/960,(size.Y-24)/620))
 local half=Vector2.new(480,310)*scale.Scale
 local center=Vector2.new(window.Position.X.Scale*size.X+window.Position.X.Offset,window.Position.Y.Scale*size.Y+window.Position.Y.Offset)
 window.Position=UDim2.fromOffset(math.clamp(center.X,half.X,size.X-half.X),math.clamp(center.Y,half.Y,size.Y-half.Y))
end
local dragging, start, origin
on(header.InputBegan,function(input)
 if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
  if input.Position.X>header.AbsolutePosition.X+830*scale.Scale then return end
  dragging=input start=input.Position origin=window.Position
 end
end)
on(Input.InputChanged,function(input)
 if dragging and (input==dragging or input.UserInputType==Enum.UserInputType.MouseMovement) then
  local delta=input.Position-start
  local size=gui.AbsoluteSize
  local half=Vector2.new(480,310)*scale.Scale
  window.Position=UDim2.fromOffset(math.clamp(origin.X.Offset+delta.X,half.X,size.X-half.X),math.clamp(origin.Y.Offset+delta.Y,half.Y,size.Y-half.Y))
 end
end)
on(Input.InputEnded,function(input) if input==dragging then dragging=nil fit() end end)
on(gui:GetPropertyChangedSignal("AbsoluteSize"),fit)
on(window:GetPropertyChangedSignal("Visible"),function() launcher.Visible=not window.Visible dragging=nil end)
on(Input.WindowFocusReleased,function() dragging=nil end)
-- One shared clock, capped at 20 updates/second. No ambient tasks per control.
local accumulated, phase=0,0
on(RunService.RenderStepped,function(delta)
 if not window.Visible or reduced or not auraEnabled then accumulated=0 return end
 accumulated+=delta
 if accumulated<.05 then return end
 local step=math.min(accumulated,.15)
 accumulated=0
 phase+=step
 borderGradient.Rotation=(phase*7)%360
 if active==names[1] then
  for _,entry in ipairs(ambient) do entry.object.Rotation=(phase*entry.speed)%360 end
  for index,stroke in ipairs(auraStrokes) do stroke.Transparency=.945+math.sin(phase*.9+index*.4)*.018 end
 end
end)
on(Input.InputBegan,function(input,processed)
 if not processed and input.KeyCode==Enum.KeyCode.RightControl then window.Visible=not window.Visible end
end)
on(gui.Destroying,function()
 dead=true
 for _,connection in ipairs(connections) do connection:Disconnect() end
 for _,tween in pairs(tweens) do tween:Cancel() end
end)
selectPage(names[1])
task.defer(function()
 if dead then return end
 fit()
 local target=scale.Scale
 scale.Scale=target*.975
 animate(scale,{Scale=target})
 if LOGO_ASSET=="" then notify("Logo cần asset ID Roblox. Xem KYVORIX-README.txt để gắn logo tách nền.") end
end)


